import re

def calc(expr):
    # Remove whitespace
    expr = expr.strip()

    # Check if the input is empty
    if not expr:
        return 'error'

    # Check if the input matches the expected format
    match = re.match(r'^(\d+)([+-])(\d+)$', expr)
    if not match:
        return 'error'

    # Extract the integers
    num1, op, num2 = match.groups()

    # Evaluate the expression
    if op == '+':
        return str(int(num1) + int(num2))
    elif op == '-':
        return str(int(num1) - int(num2))
    else:
        return 'error'
